@dataclass(frozen=True)
class DccOperation:
    key: str
    label: str
    function: str
    required: tuple[str, ...] = ()
    optional: dict = None
    mutates_project: bool = False

def dcc_operation_registry(host):
    if host == 'blender':
        return {'blender.scan_animation': DccOperation('blender.scan_animation', 'Scan Blender Animation', 'tech_connector.services.dcc.dcc_operation_service.blender.scan_animation', ('armature_name',), {}, False)}
    if host == 'maya':
        return {'maya.scan_facial_rig': DccOperation('maya.scan_facial_rig', 'Scan Maya Facial Rig', 'ai_studio.maya.generated.maya_scan_facial_rig', (), {}, False)}
    return {}

class CommandRouter:
    def __init__(self):
        self.calls = []
    def execute_unreal_operation(self, operation_key, params):
        self.calls.append(('unreal', operation_key, params))
        return 'Fake Unreal Backend', True, {'status': 'backend_called', 'operation': operation_key, 'params': params}
    def execute_registered_dcc_operation(self, host, operation_key, params):
        self.calls.append((host, operation_key, params))
        return f'{host.title()} Backend', True, {'status': 'dcc_backend_called', 'host': host, 'operation': operation_key, 'params': params}

