except Exception:
    class Qt:
        UserRole = 32
    class Signal:
        def __init__(self, *args):
            self.events = []
            self.callbacks = []
        def emit(self, *args):
            self.events.append(args)
            for callback in self.callbacks:
                callback(*args)
        def connect(self, callback):
            self.callbacks.append(callback)
    class QThread:
        def start(self):
            self.run()
        def wait(self, timeout=0):
            return True
    class QWidget:
        def __init__(self, *args):
