    def _build_layout(self):
        filters = QHBoxLayout()
        filters.addWidget(QLabel('Host'))
        filters.addWidget(self.host_filter)
        filters.addWidget(QLabel('Search'))
        filters.addWidget(self.search_edit, 1)
        layout = QVBoxLayout(self)
        layout.addLayout(filters)
        layout.addWidget(self.operation_table, 2)
        layout.addWidget(QLabel('Arguments'))
        layout.addWidget(self.args_editor, 1)
        layout.addWidget(self.run_button)
        layout.addWidget(self.progress_label)
        layout.addWidget(self.result_editor, 1)

