from tech_connector.services.unreal.unreal_operation_service import operation_catalog, unreal_operation_payload
from tech_connector.services.dcc.dcc_operation_service import dcc_operation_registry
from tech_connector.router.command_router import CommandRouter

@dataclass(frozen=True)
class OperationRow:
    host: str
    key: str
    label: str
    function: str
    required: tuple[str, ...] = ()
    optional: tuple[str, ...] = ()
    mutates_project: bool = False

    @classmethod
    def from_unreal(cls, item: dict[str, Any]) -> 'OperationRow':
        optional = item.get('optional') or item.get('optional_args') or ()
        optional_names = tuple(optional.keys()) if isinstance(optional, dict) else tuple(optional)
        return cls('unreal', item['key'], item.get('label', item['key']), item.get('function', ''), tuple(item.get('required') or item.get('required_args') or ()), optional_names, bool(item.get('mutates_project')))

    @classmethod
    def from_dcc(cls, host: str, item: Any) -> 'OperationRow':
        required = getattr(item, 'required', getattr(item, 'required_args', ()))
        optional = getattr(item, 'optional', getattr(item, 'optional_args', ()))
        optional_names = tuple(optional.keys()) if isinstance(optional, dict) else tuple(optional)
        return cls(host, item.key, item.label, item.function, tuple(required), optional_names, bool(item.mutates_project))

class OperationBackend:
    def __init__(self, router: Any | None = None):
        self.router = router or CommandRouter()

    def run_operation(self, host: str, operation_key: str, params: dict[str, Any]) -> dict[str, Any]:
        try:
            if host == 'unreal':
                label, ok, result = self.router.execute_unreal_operation(operation_key, params)
            elif host in {'maya', 'blender', 'houdini', 'motionbuilder', 'substance_painter', 'unity'} and hasattr(self.router, 'execute_registered_dcc_operation'):
                label, ok, result = self.router.execute_registered_dcc_operation(host, operation_key, params)
            elif host in {'maya', 'blender', 'houdini', 'motionbuilder', 'substance_painter', 'unity'}:
                return {'ok': False, 'error': 'backend_adapter_required', 'host': host, 'operation': operation_key, 'params': params}
            else:
                return {'ok': False, 'error': 'unknown_host', 'host': host, 'operation': operation_key}
            return {'ok': bool(ok), 'label': label, 'result': result, 'host': host, 'operation': operation_key}
        except Exception as exc:
            return {'ok': False, 'error': 'backend_exception', 'detail': str(exc), 'host': host, 'operation': operation_key}

class OperationRunWorker(QThread):
    progress = Signal(str)
    finished = Signal(bool, object)

    def __init__(self, host: str = '', operation_key: str = '', args_json: str = '', backend: OperationBackend | None = None):
        super().__init__()
        self.host = host
        self.operation_key = operation_key
        self.args_json = args_json
        self.backend = backend or OperationBackend()

    def run(self):
        try:
            params = json.loads(self.args_json or '{}')
        except json.JSONDecodeError as exc:
            self.finished.emit(False, {'error': 'invalid_json', 'detail': str(exc)})
            return
        self.progress.emit(f'Preparing {self.host}:{self.operation_key}')
        if self.host == 'unreal':
            payload = unreal_operation_payload(self.operation_key, params)
            params = payload['kwargs']
        elif self.operation_key not in dcc_operation_registry(self.host):
            self.finished.emit(False, {'error': 'operation_not_registered'})
            return
        result = self.backend.run_operation(self.host, self.operation_key, params)
        self.finished.emit(bool(result.get('ok')), result)

class OperationRunnerPanel(QWidget):
    def __init__(self, backend: OperationBackend | None = None):
        super().__init__()
        self.backend = backend or OperationBackend()
        self._all_rows: list[OperationRow] = []
        self._visible_rows: list[OperationRow] = []
        self.worker = None
        self.host_filter = QComboBox()
        self.host_filter.addItems(['all', 'unreal', 'blender', 'maya'])
        self.search_edit = QLineEdit()
        self.search_edit.setPlaceholderText('Search operations, labels, functions, args')
        self.operation_table = QTableWidget(0, 6)
        self.operation_table.setHorizontalHeaderLabels(['Host', 'Operation', 'Label', 'Function', 'Required', 'Mutates'])
        self.operation_table.setSelectionBehavior(QTableWidget.SelectRows)
        self.operation_table.setSelectionMode(QTableWidget.SingleSelection)
        self.args_editor = QPlainTextEdit()
        self.args_editor.setPlaceholderText('JSON arguments for the selected operation')
        self.run_button = QPushButton('Run / Queue')
        self.progress_label = QLabel('Ready')
        self.result_editor = QPlainTextEdit()
        self.result_editor.setReadOnly(True)
        self._build_layout()
        self.host_filter.currentTextChanged.connect(self.apply_filters)
        self.search_edit.textChanged.connect(self.apply_filters)
        self.operation_table.itemSelectionChanged.connect(self.populate_args_template)
        self.run_button.clicked.connect(self.run_selected_operation)
        self.refresh_catalog()

    def _build_layout(self):
        filters = QHBoxLayout()
        filters.addWidget(QLabel('Host'))
        filters.addWidget(self.host_filter)
        filters.addWidget(QLabel('Search'))
        filters.addWidget(self.search_edit, 1)
        layout = QVBoxLayout(self)
        layout.addLayout(filters)
        layout.addWidget(self.operation_table, 2)
        layout.addWidget(QLabel('Arguments'))
        layout.addWidget(self.args_editor, 1)
        layout.addWidget(self.run_button)
        layout.addWidget(self.progress_label)
        layout.addWidget(self.result_editor, 1)

    def refresh_catalog(self):
        rows = [OperationRow.from_unreal(item) for item in operation_catalog()]
        for host in ('blender', 'maya'):
            rows.extend(OperationRow.from_dcc(host, item) for item in dcc_operation_registry(host).values())
        self._all_rows = rows
        self.apply_filters()
        return len(rows)

    def apply_filters(self, *_):
        host = self.host_filter.currentText() if hasattr(self.host_filter, 'currentText') else 'all'
        query = self.search_edit.text().strip().lower() if hasattr(self.search_edit, 'text') else ''
        visible = []
        for row in self._all_rows:
            haystack = ' '.join([row.host, row.key, row.label, row.function, ' '.join(row.required), ' '.join(row.optional)]).lower()
            if host != 'all' and row.host != host:
                continue
            if query and query not in haystack:
                continue
            visible.append(row)
        self._set_rows(visible)
        return len(visible)

    def _set_rows(self, rows: list[OperationRow]):
        self._visible_rows = list(rows)
        self.operation_table.setRowCount(len(self._visible_rows))
        for index, row in enumerate(self._visible_rows):
            values = [row.host, row.key, row.label, row.function, ', '.join(row.required), 'yes' if row.mutates_project else 'no']
            for column, value in enumerate(values):
                item = QTableWidgetItem(value)
                item.setData(Qt.UserRole, row)
                self.operation_table.setItem(index, column, item)
        if self._visible_rows:
            self.operation_table.selectRow(0)
            self.populate_args_template()
        else:
            self.args_editor.setPlainText('{}')
        return len(self._visible_rows)

    def _selected_row(self) -> OperationRow:
        index = self.operation_table.currentRow()
        if index < 0 or index >= len(self._visible_rows):
            raise ValueError('operation_not_selected')
        return self._visible_rows[index]

    def populate_args_template(self):
        row = self._selected_row()
        template = {name: '' for name in (*row.required, *row.optional)}
        self.args_editor.setPlainText(json.dumps(template, indent=2))
        return template

    def run_selected_operation(self):
        try:
            row = self._selected_row()
        except ValueError as exc:
            self._on_finished(False, {'error': str(exc)})
            return
        self.run_button.setEnabled(False)
        self.progress_label.setText(f'Queued {row.host}:{row.key}')
        self.worker = OperationRunWorker(row.host, row.key, self.args_editor.toPlainText(), self.backend)
        self.worker.progress.connect(self.progress_label.setText)
        self.worker.finished.connect(self._on_finished)
        self.worker.start()

    def _on_finished(self, ok: bool, payload: object):
        self.run_button.setEnabled(True)
        self.progress_label.setText('Complete' if ok else 'Failed')
        self.result_editor.setPlainText(json.dumps({'ok': ok, 'result': payload}, indent=2, default=str))

def operation_catalog():
    return [{'key': 'blueprint.scan', 'label': 'Scan Blueprint', 'function': 'unreal_tools.blueprint.scan', 'required': ['asset_path'], 'optional': {}, 'mutates_project': False}]

def unreal_operation_payload(operation_key, params):
    if operation_key != 'blueprint.scan':
        raise ValueError('unknown operation')
    if not params.get('asset_path'):
        raise ValueError('asset_path required')
    return {'operation': operation_key, 'kwargs': dict(params)}

